import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A sheet id that was never loaded. */
@ResponseStatus(HttpStatus.NOT_FOUND)
public class SheetNotFoundException extends RuntimeException {

    public SheetNotFoundException(String id) {
        super("Sheet " + id + " not found");
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** Moves the sheet's last claim number on by one; the row stays locked until the transaction ends. */
    @Modifying
    @Query(value = "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = :id", nativeQuery = true)
    int incrementLastClaimNumber(@Param("id") String id);

    /** Locks the sheet's row until the transaction ends; 0 when the sheet does not exist. */
    @Modifying
    @Query(value = "UPDATE sheet SET id = id WHERE id = :id", nativeQuery = true)
    int lockById(@Param("id") String id);

    @Query(value = "SELECT last_claim_number FROM sheet WHERE id = :id", nativeQuery = true)
    long lastClaimNumber(@Param("id") String id);
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Loads a sheet by id, starting an empty one the first time the id is used, and keeps the sheet's
 * today. The real clock is read only once, to give a new sheet its starting today; everything else
 * dated uses {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;

    public SheetService(SheetRepository sheets, RollupService rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> start(id, user));
    }

    /** The sheet's today: use it for every date-dependent decision and default date. */
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseThrow(() -> new SheetNotFoundException(id));
    }

    /** Change the sheet's today; it has no audit record of its own, only the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = sheets.findById(id).orElseThrow(() -> new SheetNotFoundException(id));
        RollupService.Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        rollup.recordChanges(id, user, before);
        return saved;
    }

    /**
     * The next claim number on the sheet: 1 for the first, then 2, and so on. The sheet's row is
     * locked until the caller's transaction ends, so two claims opened at once get different numbers.
     */
    @Transactional
    public long nextClaimNumber(String id) {
        if (sheets.incrementLastClaimNumber(id) != 1) {
            throw new SheetNotFoundException(id);
        }
        return sheets.lastClaimNumber(id);
    }

    private Sheet start(String id, String user) {
        try {
            return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
        } catch (DataIntegrityViolationException e) {
            // Another user started the same sheet at the same moment: it exists now.
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }
}
-- A sheet is the unit everything else in the app is kept under. It is created the first time its
-- id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL
);
-- Each sheet keeps its own "today": every date-dependent decision and default date uses it, never
-- the real clock. A sheet starts with the real date of the day it was created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
-- A claim's due as it was when it was settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Null while the claim is not settled, or when the grade had no rate
-- (that due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
